// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Get(options.BaseURL+"/v1/status", wrapper.GetStatus)

	router.Get(options.BaseURL+"/v1/accounts", wrapper.ListAccounts)

	router.Post(options.BaseURL+"/v1/accounts", wrapper.ImportAccount)

	router.Post(options.BaseURL+"/v1/accounts/adopt", wrapper.AdoptAccount)

	router.Delete(options.BaseURL+"/v1/accounts/:name", wrapper.RemoveAccount)

	router.Patch(options.BaseURL+"/v1/accounts/:name", wrapper.PatchAccount)

	router.Post(options.BaseURL+"/v1/accounts/:name/activate", wrapper.ActivateAccount)

	router.Put(options.BaseURL+"/v1/auto", wrapper.SetAuto)

	router.Put(options.BaseURL+"/v1/remote", wrapper.SetRemote)

	router.Put(options.BaseURL+"/v1/strategy", wrapper.SetStrategy)

	router.Put(options.BaseURL+"/v1/lang", wrapper.SetLang)

	router.Put(options.BaseURL+"/v1/thresholds", wrapper.SetThresholds)

	router.Post(options.BaseURL+"/v1/web/code", wrapper.CreateWebCode)

	router.Post(options.BaseURL+"/v1/web/session", wrapper.OpenWebSession)

	router.Post(options.BaseURL+"/v1/migrate/export", wrapper.MigrateExport)

	router.Post(options.BaseURL+"/v1/migrate/commit", wrapper.MigrateCommit)

	router.Post(options.BaseURL+"/v1/migrate/cancel", wrapper.MigrateCancel)

	router.Post(options.BaseURL+"/v1/migrate/import", wrapper.MigrateImport)

	router.Get(options.BaseURL+"/v1/events", wrapper.GetEvents)

	router.Get(options.BaseURL+"/v1/i18n/:lang", wrapper.GetI18n)

	router.Post(options.BaseURL+"/v1/refresh", wrapper.Refresh)

	router.Post(options.BaseURL+"/v1/signal", wrapper.Signal)

}

