type GetEvents200TexteventStreamResponse struct {
	Body          io.Reader
	ContentLength int64
}

func (response GetEvents200TexteventStreamResponse) VisitGetEventsResponse(ctx fiber.Ctx) error {
	ctx.Response().Header.Set("Content-Type", "text/event-stream")
	if response.ContentLength != 0 {
		ctx.Response().Header.Set("Content-Length", fmt.Sprint(response.ContentLength))
	}
	ctx.Status(200)

	// Fiber/fasthttp streams through a callback: fasthttp emits
	// a chunk each time we call w.Flush(), so clients see
	// streaming data immediately instead of waiting on buffering.
	ctx.Response().SetBodyStreamWriter(func(w *bufio.Writer) {
		if closer, ok := response.Body.(io.ReadCloser); ok {
			defer closer.Close()
		}
		buf := make([]byte, 4096)
		for {
			n, err := response.Body.Read(buf)
			if n > 0 {
				if _, writeErr := w.Write(buf[:n]); writeErr != nil {
					return
				}
				if flushErr := w.Flush(); flushErr != nil {
					return
				}
			}
			if err != nil {
				return
			}
		}
	})
	return nil
}

